  const GEMINI_38_PROMO_END_UTC = Date.UTC(2027, 0, 1);
  const GEMINI_38_PROMO = { input_per_mtok: 0.75, output_per_mtok: 3.75, cache_read_per_mtok: 0.075, cache_write_per_mtok: 0.75 };
